1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/axilfetch.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is a very simple instruction fetch approach based around
8	//		AXI-lite.
9	//
10	// Creator:	Dan Gisselquist, Ph.D.
11	//		Gisselquist Technology, LLC
12	//
13	////////////////////////////////////////////////////////////////////////////////
14	// }}}
15	// Copyright (C) 2020-2025, Gisselquist Technology, LLC
16	// {{{
17	// This program is free software (firmware): you can redistribute it and/or
18	// modify it under the terms of the GNU General Public License as published
19	// by the Free Software Foundation, either version 3 of the License, or (at
20	// your option) any later version.
21	//
22	// This program is distributed in the hope that it will be useful, but WITHOUT
23	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
24	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
25	// for more details.
26	//
27	// You should have received a copy of the GNU General Public License along
28	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
29	// target there if the PDF file isn't present.)  If not, see
30	// <http://www.gnu.org/licenses/> for a copy.
31	// }}}
32	// License:	GPL, v3, as defined and found on www.gnu.org,
33	// {{{
34	//		http://www.gnu.org/licenses/gpl.html
35	//
36	////////////////////////////////////////////////////////////////////////////////
37	//
38	`default_nettype	none
39	// }}}
40	module	axilfetch #(
41			// {{{
42			parameter	C_AXI_ADDR_WIDTH = 32,
43			parameter	C_AXI_DATA_WIDTH = 64,
44			parameter	INSN_WIDTH=32,
45			parameter	FETCH_LIMIT=16,
46			parameter [0:0]	SWAP_ENDIANNESS = 1'b0,
47			localparam	AW=C_AXI_ADDR_WIDTH
48			// }}}
49		) (
50			// {{{
51			input	wire		S_AXI_ACLK,
52			input	wire		S_AXI_ARESETN,
53			//
54			// CPU interaction wires
55			// {{{
56			input	wire			i_cpu_reset,
57			input	wire			i_new_pc,
58			input	wire			i_clear_cache,
59			input	wire			i_ready,
60			input	wire	[AW-1:0]	i_pc,	// Ignd unls i_new_pc
61			output	wire [INSN_WIDTH-1:0]	o_insn,	// Insn read from bus
62			output	reg	[AW-1:0]	o_pc,	// Addr of that insn
63			output	reg			o_valid,	// If valid
64			output	reg			o_illegal,	// Bus error
65			// }}}
66			// AXI-lite bus interface
67			// {{{
68			output	reg				M_AXI_ARVALID,
69			input	wire				M_AXI_ARREADY,
70			output	reg [C_AXI_ADDR_WIDTH-1:0]	M_AXI_ARADDR,
71			// Verilator coverage_off
72			output	wire	[2:0]			M_AXI_ARPROT,
73			// Verilator coverage_on
74			//
75			input	wire				M_AXI_RVALID,
76			output	wire				M_AXI_RREADY,
77			input	wire [C_AXI_DATA_WIDTH-1:0]	M_AXI_RDATA,
78			input	wire [1:0]			M_AXI_RRESP
79			// }}}
80			// }}}
81		);
82	
83		// Declarations
84		// {{{
85		localparam	AXILLSB = $clog2(C_AXI_DATA_WIDTH/8);
86		localparam	INSNS_PER_WORD = C_AXI_DATA_WIDTH / INSN_WIDTH;
87		localparam	INSN_LSB = $clog2(INSN_WIDTH/8);
88		localparam	LGDEPTH = $clog2(FETCH_LIMIT)+4;
89		localparam	LGFIFO = $clog2(FETCH_LIMIT);
90		localparam	W = LGDEPTH;
91		localparam	FILLBITS = $clog2(INSNS_PER_WORD);
92				// ($clog2(INSNS_PER_WORD) > 0)
93				//			? $clog2(INSNS_PER_WORD) : 1);
94	
95		reg	[W:0]			new_flushcount, outstanding,
96						next_outstanding, flushcount;
97		reg				flushing, flush_request, full_bus;
98		wire	[((AXILLSB>INSN_LSB) ? (AXILLSB-INSN_LSB-1):0):0]	shift;
99		wire				fifo_reset, fifo_wr, fifo_rd;
100		wire				ign_fifo_full, fifo_empty;
101		wire	[LGFIFO:0]		ign_fifo_fill;
102		wire	[C_AXI_DATA_WIDTH:0]	fifo_data;
103		reg				pending_new_pc;
104		reg	[C_AXI_ADDR_WIDTH-1:0]	pending_pc;
105		reg	[W-1:0]			fill;
106		reg [FILLBITS:0]	out_fill;
107		reg	[C_AXI_DATA_WIDTH-1:0]	out_data;
108		reg	[C_AXI_DATA_WIDTH-1:0]	endian_swapped_rdata;
109	`ifdef	FORMAL
110		wire				f_cache_valid;
111		wire	[C_AXI_DATA_WIDTH-1:0]	f_cache_data;
112		wire				f_cache_illegal;
113		wire	[LGFIFO:0]		f_cache_distance;
114	`endif
115		// }}}
116	
117		assign	fifo_reset = i_cpu_reset || i_clear_cache || i_new_pc;
118		assign	fifo_wr = M_AXI_RVALID && !flushing;
119	
120	
121		// ARPROT = 3'b100 for an unprivileged, secure instruction access
122		// (not sure what unprivileged or secure mean--even after reading the
123		//  spec)
124		assign	M_AXI_ARPROT = 3'b100;
125	
126		// next_outstanding
127		// {{{
128		always @(*)
129		begin
130			next_outstanding = outstanding;
131	
132			case({ M_AXI_ARVALID && M_AXI_ARREADY, M_AXI_RVALID })
133			2'b10: next_outstanding = outstanding + 1;
134			2'b01: next_outstanding = outstanding - 1;
135			default: begin end
136			endcase
137		end
138		// }}}
139	
140		// outstanding, full_bus
141		// {{{
142		initial	outstanding = 0;
143		initial	full_bus    = 0;
144		always @(posedge S_AXI_ACLK)
145		if (!S_AXI_ARESETN)
146		begin
147			outstanding <= 0;
148			full_bus <= 0;
149		end else begin
150			outstanding <= next_outstanding;
151			full_bus <= (next_outstanding
152				// + (((M_AXI_ARVALID && !M_AXI_ARREADY) ? 1:0)
153							>= (1<<LGDEPTH)-1);
154		end
155		// }}}
156	
157		// fill
158		// {{{
159		initial	fill = 0;
160		always @(posedge S_AXI_ACLK)
161		if (fifo_reset)
162			fill <= 0;
163		// else if (fo_reset || flushing)
164		//	fill <= 0;
165		else case({ M_AXI_ARVALID && M_AXI_ARREADY && !flush_request,
166					fifo_rd && !fifo_empty })
167		2'b10: fill <= fill + 1;
168		2'b01: fill <= fill - 1;
169		default: begin end
170		endcase
171		// }}}
172	
173		// new_flushcount
174		// {{{
175		always @(*)
176			new_flushcount = outstanding + (M_AXI_ARVALID ? 1:0)
177					- (M_AXI_RVALID ? 1:0);
178		// }}}
179	
180		// flushcount, flushing, flush_request
181		// {{{
182		initial	flushcount = 0;
183		initial	flushing   = 0;
184		initial	flush_request = 0;
185		always @(posedge S_AXI_ACLK)
186		if (!S_AXI_ARESETN)
187		begin
188			flushcount <= 0;
189			flushing   <= 0;
190			flush_request <= 0;
191		end else if (fifo_reset)
192		begin
193			flushcount <= new_flushcount;
194			flushing   <= (new_flushcount > 0);
195			flush_request <= (M_AXI_ARVALID && !M_AXI_ARREADY);
196		end else begin
197			if (M_AXI_RVALID && flushcount > 0)
198			begin
199				flushcount <= flushcount - 1;
200				// Verilator lint_off CMPCONST
201				flushing   <= (flushcount > 1);
202				// Verilator lint_on  CMPCONST
203			end
204	
205			if (M_AXI_ARREADY)
206				flush_request <= 0;
207		end
208		// }}}
209	
210		// M_AXI_ARVALID
211		// {{{
212		initial	M_AXI_ARVALID = 1'b0;
213		always @(posedge S_AXI_ACLK)
214		if (!S_AXI_ARESETN)
215			M_AXI_ARVALID <= 1'b0;
216		else if (!M_AXI_ARVALID || M_AXI_ARREADY)
217		begin
218			M_AXI_ARVALID <= 1;
219			if (i_new_pc || pending_new_pc)
220				M_AXI_ARVALID <= 1'b1;
221	
222			//
223			// Throttle the number of requests we make
224			// Verilator lint_off CMPCONST
225			// Verilator lint_off WIDTH
226			//	out_fill will only capture 0 or 1 if DATA_WIDTH == 32
227			if (fill + (M_AXI_ARVALID ? 1:0)
228					+ ((o_valid &&(!i_ready || out_fill > 1)) ? 1:0)
229					>= FETCH_LIMIT)
230				M_AXI_ARVALID <= 1'b0;
231			// Verilator lint_on  WIDTH
232			// Verilator lint_on  CMPCONST
233			if (i_cpu_reset || i_clear_cache || full_bus)
234				M_AXI_ARVALID <= 1'b0;
235		end
236		// }}}
237	
238		assign	M_AXI_RREADY = 1'b1;
239	
240		// pending_new_pc
241		// {{{
242		initial	pending_new_pc = 0;
243		always @(posedge S_AXI_ACLK)
244		if (!S_AXI_ARESETN || i_clear_cache)
245			pending_new_pc <= 1'b0;
246		else if (!M_AXI_ARVALID || M_AXI_ARREADY)
247			pending_new_pc <= 1'b0;
248		else if (i_new_pc)
249			pending_new_pc <= 1'b1;
250		// }}}
251	
252		// pending_pc
253		// {{{
254		initial	pending_pc = 0;
255		always @(posedge S_AXI_ACLK)
256		if (i_new_pc)
257			pending_pc <= i_pc;
258		// }}}
259	
260		// M_AXI_ARADDR
261		// {{{
262		always @(posedge S_AXI_ACLK)
263		if (!M_AXI_ARVALID || M_AXI_ARREADY)
264		begin
265			if (i_new_pc)
266				M_AXI_ARADDR <= i_pc;
267			else if (pending_new_pc)
268				M_AXI_ARADDR <= pending_pc;
269			else if (M_AXI_ARVALID)
270			begin
271				M_AXI_ARADDR[C_AXI_ADDR_WIDTH-1:AXILLSB]
272					<= M_AXI_ARADDR[C_AXI_ADDR_WIDTH-1:AXILLSB] +1;
273				M_AXI_ARADDR[AXILLSB-1:0] <= 0;
274			end
275		end
276		// }}}
277	
278		// o_pc
279		// {{{
280		initial	o_pc = 0;
281		always @(posedge S_AXI_ACLK)
282		if (i_new_pc)
283			o_pc <= i_pc;
284		else if (o_valid && i_ready && !o_illegal)
285		begin
286			o_pc <= 0;
287			o_pc[AW-1:INSN_LSB] <= o_pc[AW-1:INSN_LSB] + 1;
288		end
289		// }}}
290	
291		generate if (AXILLSB > INSN_LSB)
292		begin : BIG_WORD
293			// {{{
294			assign	shift = o_pc[AXILLSB-1:INSN_LSB];
295			// }}}
296		end else begin : NO_SHIFT
297			// {{{
298			assign	shift = 0;
299			// }}}
300		end endgenerate
301	
302		generate if (SWAP_ENDIANNESS)
303		begin : SWAPPED_ENDIANNESS
304			// {{{
305			genvar	gw, gb;	// Word count, byte count
306	
307			for(gw=0; gw<C_AXI_DATA_WIDTH/INSN_WIDTH; gw=gw+1) // For each bus word
308			begin : FOR_INSN_WORD
309				for(gb=0; gb<(INSN_WIDTH/8); gb=gb+1) // For each bus byte
310				begin : FOR_INSN_BYTE
311					always @(*)
312						endian_swapped_rdata[gw*INSN_WIDTH
313							+ ((INSN_WIDTH/8)-1-gb)*8 +: 8]
314					= M_AXI_RDATA[gw*INSN_WIDTH+gb*8 +: 8];
315				end
316			end
317			// }}}
318		end else begin : NO_ENDIAN_SWAP
319			// {{{
320			always @(*)
321				endian_swapped_rdata = M_AXI_RDATA;
322			// }}}
323		end endgenerate
324	
325		generate if (FETCH_LIMIT <= 1)
326		begin : NOCACHE
327			// {{{
328			// No cache
329	
330			// assign	fifo_rd    = fifo_wr;
331			// Verilator lint_off CMPCONST
332			assign	fifo_rd = !o_valid || (i_ready && (out_fill <= 1));
333			// Verilator lint_on  CMPCONST
334			assign	fifo_empty = !fifo_wr; //(out_fill <= (i_aready ? 1:0));
335			assign	fifo_data  = { M_AXI_RRESP[1], endian_swapped_rdata };
336	
337			assign	ign_fifo_fill = 1'b0;
338			assign	ign_fifo_full = 1'b0;
339	`ifdef	FORMAL
340			always @(*)
341			if (M_AXI_RVALID || M_AXI_ARVALID || outstanding > 0)
342				assert(!o_valid);
343	
344			assign	f_cache_valid   = 1'b0;
345			assign	f_cache_data    = 0;
346			assign	f_cache_illegal = 1'b0;
347			assign	f_cache_distance= 0;
348	`endif
349			// }}}
350		end else if (FETCH_LIMIT == 2)
351		begin : DBLFETCH
352			// {{{
353			// Single word cache
354			reg				cache_valid;
355			reg	[C_AXI_DATA_WIDTH:0]	cache_data;
356	
357			// Verilator lint_off CMPCONST
358			assign	fifo_rd = !o_valid || (i_ready && (out_fill <= 1));
359			// Verilator lint_on  CMPCONST
360			assign	fifo_empty =(!M_AXI_RVALID && !cache_valid) || flushing;
361			assign	fifo_data = cache_valid ? cache_data
362						: ({ M_AXI_RRESP[1], endian_swapped_rdata });
363	
364	
365			assign	ign_fifo_fill = cache_valid ? 1 : 0;
366			assign	ign_fifo_full = cache_valid;
367	
368			initial	cache_valid = 1'b0;
369			always @(posedge S_AXI_ACLK)
370			if (fifo_reset)
371				cache_valid <= 1'b0;
372			else if (M_AXI_RVALID && o_valid && !fifo_rd)
373				cache_valid <= 1;
374			else if (fifo_rd)
375				cache_valid <= 1'b0;
376	
377			always @(posedge S_AXI_ACLK)
378			if (M_AXI_RVALID)
379				cache_data <= { M_AXI_RRESP[1], endian_swapped_rdata };
380	
381			// Keep Verilator happy
382			// {{{
383			// Verilator coverage_off
384			// Verilator lint_off UNUSED
385			wire	unused_dbl;
386			assign	unused_dbl = &{ 1'b0, fifo_wr };
387			// Verilator lint_on  UNUSED
388			// Verilator coverage_on
389			// }}}
390	`ifdef	FORMAL
391			assign	f_cache_valid = cache_valid;
392			assign	{ f_cache_illegal, f_cache_data }  = cache_data;
393			assign	f_cache_distance= 0;
394	`endif
395			// }}}
396		end else begin : FIFO_FETCH
397			// {{{
398			// FIFO cache
399	`ifdef	FORMAL
400			wire	[LGFIFO:0]	f_first_addr;
401			wire	[LGFIFO:0]	f_second_addr;
402			wire	[C_AXI_DATA_WIDTH:0]	f_first_data, f_second_data;
403	
404			wire			f_first_in_fifo,
405						f_second_in_fifo;
406			wire	[LGFIFO:0]	f_distance_to_first,
407						f_distance_to_second;
408	`endif
409	
410	
411			// Verilator lint_off CMPCONST
412			//	out_fill will only capture 0 or 1 if DATA_WIDTH == 32
413			assign	fifo_rd = !o_valid || (i_ready && (out_fill <= 1));
414			// Verilator lint_on  CMPCONST
415	
416			sfifo #(
417				// {{{
418				.BW(1+C_AXI_DATA_WIDTH), .LGFLEN(LGFIFO)
419				// }}}
420			) fcache(
421				// {{{
422				.i_clk(S_AXI_ACLK), .i_reset(fifo_reset),
423				.i_wr(fifo_wr),
424				.i_data({M_AXI_RRESP[1], endian_swapped_rdata }),
425				.o_full(ign_fifo_full), .o_fill(ign_fifo_fill),
426				.i_rd(fifo_rd),.o_data(fifo_data),.o_empty(fifo_empty)
427	`ifdef	FORMAL
428				// {{{
429				, .f_first_addr(f_first_addr),
430				.f_second_addr(f_second_addr),
431				.f_first_data(f_first_data),
432				.f_second_data(f_second_data),
433	
434				.f_first_in_fifo(f_first_in_fifo),
435				.f_second_in_fifo(f_second_in_fifo),
436				.f_distance_to_first(f_distance_to_first),
437				.f_distance_to_second(f_distance_to_second)
438				// }}}
439	`endif
440				// }}}
441			);
442	
443	`ifdef	FORMAL
444			assign	{ f_cache_illegal, f_cache_data } = f_first_data;
445			assign	f_cache_distance = f_distance_to_first;
446			assign	f_cache_valid = f_first_in_fifo;
447	`endif
448			// }}}
449		end endgenerate
450	
451		// o_valid
452		// {{{
453		initial	o_valid = 1'b0;
454		always @(posedge S_AXI_ACLK)
455		if (fifo_reset)
456			o_valid <= 1'b0;
457		else if (!o_valid || i_ready)
458			o_valid <= (fifo_rd && !fifo_empty)
459				|| out_fill > (o_valid ? 1:0);
460		// }}}
461	
462		// out_fill
463		// {{{
464		// == number of instructions in the fifo_data word that have not (yet)
465		//	been accepted by the CPU.
466		// == 0 when no data is available
467		// == INSN_PER_WORD on the first instruction of any word
468		// == 1 on the last instruction of any word
469		initial	out_fill = 0;
470		always @(posedge S_AXI_ACLK)
471		if (fifo_reset)
472			out_fill <= 0;
473		else if (fifo_rd)
474		begin
475			if (fifo_empty)
476				out_fill <= 0;
477			else if (o_valid)
478				out_fill <= INSNS_PER_WORD[FILLBITS:0];
479			else
480				// Verilator lint_off WIDTH
481				out_fill <= (INSNS_PER_WORD[FILLBITS:0] - shift);
482				// Verilator lint_on  WIDTH
483		end else if (i_ready && out_fill > 0)
484			out_fill <= out_fill - 1;
485		// }}}
486	
487		// out_data
488		// {{{
489		always @(posedge S_AXI_ACLK)
490		if (fifo_rd)
491		begin
492			if (o_valid || (INSN_WIDTH == C_AXI_DATA_WIDTH))
493				out_data <= fifo_data[C_AXI_DATA_WIDTH-1:0];
494			else
495			out_data <= fifo_data[C_AXI_DATA_WIDTH-1:0]>>(INSN_WIDTH*shift);
496		end else if (i_ready)
497			out_data <= out_data >> INSN_WIDTH;
498		// }}}
499	
500		assign	o_insn = out_data[INSN_WIDTH-1:0];
501	
502		// o_illegal
503		// {{{
504		initial	o_illegal = 1'b0;
505		always @(posedge S_AXI_ACLK)
506		if (fifo_reset)
507			o_illegal <= 1'b0;
508		else if (!o_illegal && fifo_rd && !fifo_empty)
509			o_illegal <= fifo_data[C_AXI_DATA_WIDTH];
510		// }}}
511	
512		// Make verilator happy
513		// {{{
514		// Verilator coverage_off
515		// verilator lint_off UNUSED
516		wire	unused;
517		assign	unused = & { 1'b0, M_AXI_RRESP[0], ign_fifo_full, ign_fifo_fill };
518		// verilator lint_on  UNUSED
519		// Verilator coverage_on
520		// }}}
521	////////////////////////////////////////////////////////////////////////////////
522	////////////////////////////////////////////////////////////////////////////////
523	////////////////////////////////////////////////////////////////////////////////
524	//
525	// Formal properties
526	// {{{
527	////////////////////////////////////////////////////////////////////////////////
528	////////////////////////////////////////////////////////////////////////////////
529	////////////////////////////////////////////////////////////////////////////////
530	`ifdef	FORMAL
531		// Declarations
532		// {{{
533		localparam	DW=INSN_WIDTH;
534		localparam	F_LGDEPTH=LGDEPTH+2;
535		reg	f_past_valid;
536		wire	[(F_LGDEPTH-1):0]	faxil_outstanding;
537		// Verilator lint_off UNUSED
538		wire	[(F_LGDEPTH-1):0]	faxil_awr_outstanding,
539						faxil_wr_outstanding;
540		// Verilator lint_on  UNUSED
541		reg	[(AW-1):0]	f_last_pc;
542		reg			f_last_pc_valid;
543		//
544		reg	[AW-1:0]	fc_pc, f_address;
545		reg			fc_illegal;
546		reg [INSN_WIDTH-1:0]	fc_insn;
547		//}}}
548		////////////////////////////////////////////////////////////////////////
549		//
550		// Generic setup
551		// {{{
552		////////////////////////////////////////////////////////////////////////
553		//
554		//
555	
556		// Keep track of a flag telling us whether or not $past()
557		// will return valid results
558		initial	f_past_valid = 1'b0;
559		always @(posedge S_AXI_ACLK)
560			f_past_valid <= 1'b1;
561		// }}}
562		////////////////////////////////////////////////////////////////////////
563		//
564		// Assumptions about our inputs
565		// {{{
566		////////////////////////////////////////////////////////////////////////
567		//
568		//
569	
570		// Assume we start from a reset condition
571		// {{{
572		always @(*)
573		if (!f_past_valid)
574			assume(!S_AXI_ARESETN);
575	
576		always @(*)
577		if (!S_AXI_ARESETN)
578			assume(i_cpu_reset);
579		// }}}
580	
581		//
582		//
583		// Let's make some assumptions about how long it takes our
584		// phantom bus and phantom CPU to respond.
585		//
586		// These delays need to be long enough to flush out any potential
587		// errors, yet still short enough that the formal method doesn't
588		// take forever to solve.
589		//
590		localparam	F_CPU_DELAY = 4;
591		reg	[$clog2(F_CPU_DELAY):0]	f_cpu_delay;
592		// First, let's assume that any response from the bus comes back
593		// within F_WB_DELAY clocks
594	
595			// Here's our delay assumption: We'll assume that the
596		// wishbone will always respond within F_WB_DELAY clock ticks
597		// of the beginning of any cycle.
598		//
599		// This includes both dropping the stall line, as well as
600		// acknowledging any request.  While this may not be
601		// a reasonable assumption for a piped master, it should
602		// work here for us.
603	
604		// Count the number of clocks it takes the CPU to respond to our
605		// instruction.
606		always @(posedge S_AXI_ACLK)
607		// If no instruction is ready, then keep our counter at zero
608		if (i_cpu_reset|| !o_valid || i_ready)
609			f_cpu_delay <= 0;
610		else
611			// Otherwise, count the clocks the CPU takes to respond
612			f_cpu_delay <= f_cpu_delay + 1'b1;
613	
614	`ifdef	PREFETCH
615		// Only *assume* that we are less than F_CPU_DELAY if we are not
616		// integrated into the CPU
617		always @(posedge S_AXI_ACLK)
618			assume(f_cpu_delay < F_CPU_DELAY);
619	`endif
620		// }}}
