1141			begin
1142				assume(f_fifo_subdata[INSN_WIDTH-1:0] == fc_insn);
1143				assume(fifo_data[C_AXI_DATA_WIDTH] == fc_illegal);
1144			end
1145			// }}}
1146		end endgenerate
1147	
1148		//
1149		// Check the final output word
1150		// This checks all instruction positions within that word
1151		always @(*)
1152		if ((out_fill > 0)
1153			&& (fc_pc[AW-1:AXILLSB] == f_out_addr[AW-1:AXILLSB]))
1154		begin
1155			if (fc_illegal)
1156			begin
1157				assert(o_illegal);
1158			end else if (!o_illegal && fc_pc >= f_subout_addr)
1159				assert(f_out_data == fc_insn);
1160		end
1161	
1162		always @(*)
1163		if (pending_new_pc)
1164			assert(i_new_pc || flush_request);
1165	
1166		always @(*)
1167		if (pending_new_pc)
1168			assert(o_pc == pending_pc);
1169	
1170		// Verilator lint_off WIDTH
1171		always @(*)
1172		if (flush_request)
1173			assert(flushcount == faxil_outstanding + 1);
1174		// Verilator lint_on  WIDTH
1175	
1176		always @(*)
1177		if (flushing)
1178			assert(!o_illegal);
1179	
1180		always @(*)
1181		if (flush_request && !i_cpu_reset && !i_new_pc && !i_clear_cache)
1182		begin
1183			assert(f_out_addr[AW-1:AXILLSB] == pending_pc[AW-1:AXILLSB]);
1184			assert(o_pc == pending_pc);
1185		end
1186	`endif
1187		// }}}
1188		////////////////////////////////////////////////////////////////////////
1189		//
1190		// Cover properties
1191		// {{{
1192		////////////////////////////////////////////////////////////////////////
1193		//
1194		//
1195		// Verilator lint_off UNDRIVEN
1196		(* anyconst *) reg	cvr_always_ready;
1197		// Verilator lint_on  UNDRIVEN
1198		reg	[3:0]	cvr_returns;
1199	
1200		always @(*)
1201		if (cvr_always_ready)
1202			assume(M_AXI_ARREADY);
1203	
1204		initial	cvr_returns = 0;
1205		always @(posedge S_AXI_ACLK)
1206		if (i_cpu_reset || i_new_pc || i_clear_cache || o_illegal)
1207			cvr_returns <= 0;
1208		else if (o_valid && i_ready && !cvr_returns[3])
1209			cvr_returns <= cvr_returns + 1;
1210	
1211		always @(*)
1212		begin
1213			cover(cvr_returns == 4'b0100);
1214			cover(cvr_returns == 4'b0101);
1215			cover(cvr_returns == 4'b0110 && cvr_always_ready);
1216		end
1217		// }}}
1218	
1219		// Make Verilator happy
1220		// {{{
1221		// Verilator lint_off UNUSED
1222		wire	unused_formal;
1223		assign	unused_formal = &{ 1'b0, f_ret_addr[AXILLSB-1:0] };
1224		// Verilator lint_on  UNUSED
1225		// }}}
1226	`endif
1227	// }}}
1228	endmodule
1229

