39	//
40	//
41	`default_nettype	none
42	// }}}
43	module	axilpipe #(
44			// {{{
45			parameter	ADDRESS_WIDTH=30,
46			parameter	C_AXI_ADDR_WIDTH = ADDRESS_WIDTH,
47			parameter	C_AXI_DATA_WIDTH = 32,
48			localparam	AW = C_AXI_ADDR_WIDTH,
49			localparam	DW = C_AXI_DATA_WIDTH,
50			//
51			// AXI locks are a challenge, and require support from the
52			// CPU.  Specifically, we have to be able to unroll and re-do
53			// the load instruction on any atomic access failure.  For that
54			// reason, we'll ignore the lock request initially.
55			parameter [0:0]	OPT_ALIGNMENT_ERR = 1'b1,
56			// Verilator lint_off UNUSED
57			// This *should* be used -- need to rewrite so that it is
58			parameter [0:0]	OPT_LOWPOWER = 1'b0,
59			// Verilator lint_on  UNUSED
60			parameter [0:0]	SWAP_WSTRB = 0,
61			parameter [0:0]	OPT_SIGN_EXTEND = 0
62			// }}}
63		) (
64			// {{{
65			input	wire				S_AXI_ACLK,
66			input	wire				S_AXI_ARESETN,
67			input	wire				i_cpu_reset,
68			//
69			// CPU interface
70			// {{{
71			input	wire				i_stb,
72			input	wire				i_lock,
73			input	wire	[2:0]			i_op,
74			input	wire	[31:0]			i_addr,
75			input	wire	[31:0]			i_data,
76			input	wire	[4:0]			i_oreg,
77			output	reg				o_busy,
78			output	reg				o_pipe_stalled,
79			output	reg				o_rdbusy,
80			output	reg				o_valid,
81			output	reg				o_err,
82			output	reg	[4:0]			o_wreg,
83			output	reg	[31:0]			o_result,
84			// }}}
85			//
86			// AXI-Lite bus interface
87			// {{{
88			// Writes
89			// {{{
90			output	reg			M_AXI_AWVALID,
91			input	wire			M_AXI_AWREADY,
92			output	reg	[AW-1:0]	M_AXI_AWADDR,
93			// verilator coverage_off
94			output	wire	[2:0]		M_AXI_AWPROT,
95			// verilator coverage_on
96			//
97			output	reg			M_AXI_WVALID,
98			input	wire			M_AXI_WREADY,
99			output	reg	[DW-1:0]	M_AXI_WDATA,
100			output	reg	[DW/8-1:0]	M_AXI_WSTRB,
101			//
102			input	wire			M_AXI_BVALID,
103			output	wire			M_AXI_BREADY,
104			input	wire [1:0]		M_AXI_BRESP,
105			// }}}
106			// Reads
107			// {{{
108			output	reg			M_AXI_ARVALID,
109			input	wire			M_AXI_ARREADY,
110			output	reg	[AW-1:0]	M_AXI_ARADDR,
111			// verilator coverage_off
112			output	wire	[2:0]		M_AXI_ARPROT,
113			// verilator coverage_on
114			//
115			input	wire			M_AXI_RVALID,
116			output	wire			M_AXI_RREADY,
117			input	wire	[DW-1:0]	M_AXI_RDATA,
118			input	wire	[1:0]		M_AXI_RRESP
119			// }}}
120			// }}}
121			// }}}
122		);
123	
124		// Declarations
125		// {{{
126		localparam	AXILLSB = $clog2(C_AXI_DATA_WIDTH/8);
127		localparam	AXILSB = $clog2(C_AXI_DATA_WIDTH/8);
128		localparam	LGPIPE = 4;
129		localparam	FIFO_WIDTH = AXILLSB+1+2+5 + 1;
130	
131		wire	i_clk = S_AXI_ACLK;
132	
133		reg	w_misaligned;
134		wire	misaligned_request, misaligned_aw_request, pending_err,
135				w_misalignment_err;
136		reg	[C_AXI_DATA_WIDTH-1:0]	next_wdata;
137		reg [C_AXI_DATA_WIDTH/8-1:0]	next_wstrb;
138	
139	
140		reg				none_outstanding, bus_abort,
141						read_abort, write_abort;
142		reg	[LGPIPE:0]		beats_outstanding;
143		reg				r_flushing, flush_request,
144						r_pipe_stalled;
145		reg	[LGPIPE:0]		flushcount, new_flushcount;
146		reg	[LGPIPE:0]		wraddr, rdaddr;
147		reg	[4:0]			ar_oreg;
148		reg	[1:0]			ar_op;
149		reg	[AXILSB-1:0]		adr_lsb;
150		reg	[FIFO_WIDTH-1:0]	fifo_data	[0:((1<<LGPIPE)-1)];
151		reg	[FIFO_WIDTH-1:0]	fifo_read_data;
152		wire				fifo_read_op, fifo_misaligned;
153		wire	[1:0]			fifo_op;
154		wire	[4:0]			fifo_return_reg;
155		wire	[AXILSB-1:0]		fifo_lsb;
156		reg [2*C_AXI_DATA_WIDTH-1:0]	wide_return, wide_wdata;
157		reg	[31:0]			pre_result;
158		reg [2*C_AXI_DATA_WIDTH/8-1:0]	wide_wstrb;
159		reg	[C_AXI_DATA_WIDTH-1:0]	misdata;
160	
161	
162		// }}}
163		////////////////////////////////////////////////////////////////////////
164		//
165		// Transaction issue
166		// {{{
167		////////////////////////////////////////////////////////////////////////
168		//
169		//
170	
171		// AWVALID
172		// {{{
173		initial	M_AXI_AWVALID = 0;
174		always @(posedge S_AXI_ACLK)
175		if (!S_AXI_ARESETN)
176			M_AXI_AWVALID <= 0;
177		else if (!M_AXI_AWVALID || M_AXI_AWREADY)
178		begin
179			if (i_stb && i_op[0])
180				M_AXI_AWVALID <= 1;
181			else
182				M_AXI_AWVALID <= M_AXI_AWVALID && misaligned_aw_request;
183	
184			if ((write_abort && !misaligned_aw_request)||w_misalignment_err)
185				M_AXI_AWVALID <= 0;
186		end
187		// }}}
188	
189		// WVALID
190		// {{{
191		initial	M_AXI_WVALID = 0;
192		always @(posedge S_AXI_ACLK)
193		if (!S_AXI_ARESETN)
194			M_AXI_WVALID <= 0;
195		else if (!M_AXI_WVALID || M_AXI_WREADY)
196		begin
197			if (i_stb && i_op[0])
198				M_AXI_WVALID <= 1;
199			else
200				M_AXI_WVALID <= M_AXI_WVALID && misaligned_request;
201	
202			if ((write_abort && !misaligned_request)||w_misalignment_err)
203				M_AXI_WVALID <= 0;
204		end
205		// }}}
206	
207		// ARVALID
208		// {{{
209		initial	M_AXI_ARVALID = 0;
210		always @(posedge S_AXI_ACLK)
211		if (!S_AXI_ARESETN)
212			M_AXI_ARVALID <= 0;
213		else if (!M_AXI_ARVALID || M_AXI_ARREADY)
214		begin
215			if (i_stb && !i_op[0])
216				M_AXI_ARVALID <= 1;
217			else
218				M_AXI_ARVALID <= M_AXI_ARVALID && misaligned_request;
219	
220			if ((read_abort && !misaligned_request)||w_misalignment_err)
221				M_AXI_ARVALID <= 0;
222		end
223		// }}}
224	
225		// o_busy,
226		// {{{
227		// True if the bus is busy doing ... something, whatever it might be.
228		// If the bus is busy, the CPU will avoid issuing further interactions
229		// to the bus other than pipelined interactions.
230		initial	o_busy = 0;
231		always @(posedge S_AXI_ACLK)
232		if (!S_AXI_ARESETN)
233			o_busy <= 0;
234		else if (i_stb && !w_misalignment_err && !bus_abort)
235			o_busy <= 1;
236		else if (M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID)
237			o_busy <= 1;
238		else if (beats_outstanding > ((M_AXI_RVALID || M_AXI_BVALID) ? 1:0))
239			o_busy <= 1;
240		else
241			o_busy <= 0;
242	`ifdef	FORMAL
243		always @(*)
244			assert(o_busy == (!none_outstanding || M_AXI_ARVALID
245					|| M_AXI_AWVALID || M_AXI_WVALID));
246	`endif
247		// }}}
248	
249		// Read busy
250		// {{{
251		// True if the CPU should expect some kind of pending response from a
252		// read, and so should stall for that purpose.  False otherwise.
253		initial	o_rdbusy = 0;
254		always @(posedge S_AXI_ACLK)
255		if (i_cpu_reset || r_flushing)
256			o_rdbusy <= 0;
257		else if ((i_stb && w_misalignment_err) || bus_abort)
258			o_rdbusy <= 0;
259		else if (i_stb && !i_op[0])
260			o_rdbusy <= 1;
261		else if (o_rdbusy && !M_AXI_ARVALID)
262			o_rdbusy <= (beats_outstanding > (M_AXI_RVALID ? 1:0));
263	
264	`ifdef	FORMAL
265		reg	writing;
266	
267		always @(posedge S_AXI_ACLK)
268		if (i_stb && !o_busy)
269			writing <= i_op[0];
270	
271		always @(*)
272		begin
273			if (writing)
274				assert(!o_rdbusy);
275			if (r_flushing)
276				assert(!o_rdbusy);
277			if (!o_busy)
278				assert(!o_rdbusy);
279		end
280	`endif
281		// }}}
282	
283		// o_pipe_stalled, r_pipe_stalled
284		// {{{
285		// True if the CPU should expect some kind of pending response from a
286		// read, and so should stall for that purpose.  False otherwise.
287		generate if (OPT_ALIGNMENT_ERR)
288		begin : FULL_PIPE_STALL
289			// {{{
290			// Here, we stall if the FIFO is ever full.  In this case,
291			// any new beat will count as only one item to the FIFO, and
292			// so we can run all the way to full.
293			reg	[LGPIPE:0]		beats_committed;
294	
295			always @(*)
296				beats_committed = beats_outstanding
297					+ ((i_stb && !w_misalignment_err) ? 1:0)
298					+ ((M_AXI_AWVALID || M_AXI_WVALID
299							|| M_AXI_ARVALID) ? 1:0);
300	
301			initial	r_pipe_stalled = 0;
302			always @(posedge S_AXI_ACLK)
303			if (i_cpu_reset)
304				r_pipe_stalled <= 0;
305			else if (M_AXI_RVALID || M_AXI_BVALID)
306				r_pipe_stalled <= 0;
307			else // if (!r_pipe_stalled)
308				r_pipe_stalled <= (beats_committed >= (1<<LGPIPE));
309	
310	`ifdef	FORMAL
311			always @(*)
312			if (beats_outstanding + ((M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID) ? 1:0) >= (1<<LGPIPE))
313			begin
314				assert(r_pipe_stalled || r_flushing);
315			end else if (beats_outstanding + (M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID) < (1<<LGPIPE)-1)
316				assert(!r_pipe_stalled);
317	`endif
318			// }}}
319		end else begin : PENULTIMATE_FULL_STALL
320			// {{{
321			// If we allow for misaligned reads and writes, than we have
322			// to stall the CPU just before the FIFO is full, lest the
323			// CPU send us a value that needs two items to be placed into
324			// the FIO.
325			reg	[LGPIPE:0]		beats_committed;
326	
327			always @(*)
328			begin
329				beats_committed = beats_outstanding + (i_stb ? 1:0)
330					+ ((M_AXI_AWVALID || M_AXI_WVALID
331							|| M_AXI_ARVALID) ? 1:0)
332					- ((M_AXI_BVALID || M_AXI_RVALID) ? 1:0);
333			end
334	
335			initial	r_pipe_stalled = 0;
336			always @(posedge S_AXI_ACLK)
337			if (i_cpu_reset || bus_abort)
338				r_pipe_stalled <= 0;
339			else begin
340				r_pipe_stalled <= 0;
341				if (i_stb && w_misaligned && !o_pipe_stalled)
342					r_pipe_stalled <= 1'b1;
343				if (misaligned_request && (M_AXI_WVALID && !M_AXI_WREADY))
344					r_pipe_stalled <= 1'b1;
345				if (misaligned_request && (M_AXI_ARVALID && !M_AXI_ARREADY))
346					r_pipe_stalled <= 1'b1;
347				if (misaligned_aw_request && (M_AXI_AWVALID && !M_AXI_AWREADY))
348					r_pipe_stalled <= 1'b1;
349				if (beats_committed >= (1<<LGPIPE)-2)
350					r_pipe_stalled <= 1'b1;
351			end
352	
353	`ifdef	FORMAL
354			always @(*)
355			if (!r_flushing && (beats_outstanding
356					+ (M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID)
357					+ (misaligned_aw_request || misaligned_request)
358					>= (1<<LGPIPE)))
359			begin
360				assert(r_pipe_stalled);
361			end else if (!r_flushing && !o_err
362					&& !M_AXI_AWVALID && !M_AXI_WVALID
363					&& !M_AXI_ARVALID
364					&& beats_outstanding <= ((1<<LGPIPE)-4))
365				assert(!r_pipe_stalled);
366	
367			always @(*)
368				assert(beats_committed
369					+ ((i_stb && w_misaligned && !r_pipe_stalled) ? 1:0)
370					<= (1<<LGPIPE));
371	`endif
372			// }}}
373		end endgenerate
374	
375		always @(*)
376		begin
377			o_pipe_stalled = r_pipe_stalled || r_flushing;
378			if (M_AXI_AWVALID && (!M_AXI_AWREADY || misaligned_aw_request))
379				o_pipe_stalled = 1;
380			if (M_AXI_WVALID && (!M_AXI_WREADY || misaligned_request))
381				o_pipe_stalled = 1;
382			if (M_AXI_ARVALID && (!M_AXI_ARREADY || misaligned_request))
383				o_pipe_stalled = 1;
384		end
385	`ifdef	FORMAL
386		always @(*)
387		if (misaligned_request)
388			assert(M_AXI_WVALID || M_AXI_ARVALID);
389	
390		always @(*)
391		if (misaligned_aw_request)
392			assert(M_AXI_AWVALID);
393	`endif
394		// }}}
395	
396		// Count the number of outstanding beats
397		// {{{
398		// This is the true count.  It is not affected by the number of
399		// items the CPU believes is on the bus or not.
400		initial	beats_outstanding = 0;
401		always @(posedge S_AXI_ACLK)
402		if (!S_AXI_ARESETN)
403			beats_outstanding <= 0;
404		else casez({M_AXI_AWVALID && M_AXI_AWREADY,
405			M_AXI_WVALID && M_AXI_WREADY,
406			M_AXI_ARVALID && M_AXI_ARREADY,
407			M_AXI_RVALID || M_AXI_BVALID})
408		4'b0001: beats_outstanding <= beats_outstanding - 1;
409		4'b??10: beats_outstanding <= beats_outstanding + 1;
410		4'b1100: beats_outstanding <= beats_outstanding + 1;
411		4'b1000: if (!M_AXI_WVALID || (misaligned_aw_request && !misaligned_request))
412				beats_outstanding <= beats_outstanding + 1;
413		4'b0100: if (!M_AXI_AWVALID || (misaligned_request && !misaligned_aw_request))
414				beats_outstanding <= beats_outstanding + 1;
415		4'b10?1: if ((M_AXI_WVALID && (OPT_ALIGNMENT_ERR
416					|| (misaligned_request == misaligned_aw_request)))
417				|| (!misaligned_aw_request && misaligned_request))
418				beats_outstanding <= beats_outstanding - 1;
419		4'b0101: if ((M_AXI_AWVALID && (OPT_ALIGNMENT_ERR
420					|| (misaligned_request == misaligned_aw_request)))
421				|| (!misaligned_request && misaligned_aw_request))
422				beats_outstanding <= beats_outstanding - 1;
423		default: begin end
424		endcase
425	
426		initial	none_outstanding = 1;
427		always @(posedge S_AXI_ACLK)
428		if (!S_AXI_ARESETN)
429			none_outstanding <= 1;
430		else casez({M_AXI_AWVALID && M_AXI_AWREADY,
431			M_AXI_WVALID && M_AXI_WREADY,
432			M_AXI_ARVALID && M_AXI_ARREADY,
433			M_AXI_RVALID || M_AXI_BVALID})
434		4'b0001: none_outstanding <= (beats_outstanding <= 1);
435		4'b??10: none_outstanding <= 0;
436		4'b1100: none_outstanding <= 0;
437		4'b1000: if (!M_AXI_WVALID || (misaligned_aw_request && !misaligned_request))
438				none_outstanding <= 0;
439		4'b0100: if (!M_AXI_AWVALID || (misaligned_request && !misaligned_aw_request))
440				none_outstanding <= 0;
441		4'b10?1: if ((M_AXI_WVALID && (OPT_ALIGNMENT_ERR
442					|| (misaligned_request == misaligned_aw_request)))
443				|| (!misaligned_aw_request && misaligned_request))
444				none_outstanding <= (beats_outstanding <= 1);
445		4'b0101: if ((M_AXI_AWVALID && (OPT_ALIGNMENT_ERR
446					|| (misaligned_request == misaligned_aw_request)))
447				|| (!misaligned_request && misaligned_aw_request))
448				none_outstanding <= (beats_outstanding <= 1);
449		default: begin end
450		endcase
451	`ifdef	FORMAL
452		always @(*)
453			assert(none_outstanding == (beats_outstanding == 0));
454	`endif
455		// }}}
456	
457		// bus_abort
458		// {{{
459		// When do we abandon everything and start aborting bus transactions?
460		always @(*)
461		begin
462			bus_abort = 0;
463			if (i_cpu_reset || o_err)
464				bus_abort = 1;
465			if (M_AXI_BVALID && M_AXI_BRESP[1])
466				bus_abort = 1;
467			if (M_AXI_RVALID && M_AXI_RRESP[1])
468				bus_abort = 1;
469	
470			write_abort = 0;
471			if (i_cpu_reset || o_err)
472				write_abort = 1;
473			if (M_AXI_BVALID && M_AXI_BRESP[1])
474				write_abort = 1;
475	
476			read_abort = 0;
477			if (i_cpu_reset || o_err)
478				read_abort = 1;
479			if (M_AXI_RVALID && M_AXI_RRESP[1])
480				read_abort = 1;
481		end
482		// }}}
483	
484		// Flushing
485		// {{{
486	
487		// new_flushcount
488		// {{{
489		always @(*)
490		begin
491			case({((M_AXI_AWVALID || M_AXI_WVALID) || M_AXI_ARVALID),
492				(M_AXI_BVALID || M_AXI_RVALID) })
493			2'b01: new_flushcount = beats_outstanding - 1;
494			2'b10: new_flushcount = beats_outstanding + 1;
495			default: new_flushcount = beats_outstanding;
496			endcase
497	
498			if (!OPT_ALIGNMENT_ERR && (misaligned_request || misaligned_aw_request))
499				new_flushcount = new_flushcount + 1;
500		end
501		// }}}
502	
503		initial	r_flushing    = 1'b0;
504		initial	flushcount    = 0;
505		initial	flush_request = 0;
506		always @(posedge i_clk)
507		if (!S_AXI_ARESETN)
508		begin
509			// {{{
510			r_flushing <= 1'b0;
511			flush_request <= 0;
512			flushcount    <= 0;
513			// }}}
514		end else if (i_cpu_reset || bus_abort || (i_stb && w_misalignment_err))
515		begin
516			// {{{
517			r_flushing <= (new_flushcount != 0);
518			flushcount <= new_flushcount;
519			flush_request <= (M_AXI_ARVALID && (!M_AXI_ARREADY || misaligned_request))
520				|| (M_AXI_AWVALID && (!M_AXI_AWREADY || misaligned_aw_request))
521				|| (M_AXI_WVALID && (!M_AXI_WREADY || misaligned_request));
522			// }}}
523		end else if (r_flushing)
524		begin
525			// {{{
526			if (M_AXI_BVALID || M_AXI_RVALID)
527			begin
528				flushcount <= flushcount - 1;
529				r_flushing <= (flushcount > 1);
530			end
531	
532			casez({M_AXI_AWVALID && (M_AXI_AWREADY && !misaligned_aw_request),
533					(M_AXI_WVALID && M_AXI_WREADY && !misaligned_request),
534					(M_AXI_ARVALID && M_AXI_ARREADY && !misaligned_request) })
535			3'b001: flush_request <= 0;
536			3'b10?: flush_request <= M_AXI_WVALID;
537			3'b01?: flush_request <= M_AXI_AWVALID;
538			3'b11?: flush_request <= 0;
539			default: begin end
540			endcase
541			// }}}
542		end
543	`ifdef	FORMAL
544		always @(*)
545		begin
546			assert(r_flushing == (flushcount > 0));
547			if (!r_flushing)
548			begin
549				assert(!flush_request);
550			end else
551				assert(flush_request == (M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID));
552			if (r_flushing && !flush_request)
553			begin
554				assert(!misaligned_request);
555				assert(!misaligned_aw_request);
556			end
557	
558			if (flush_request)
559			begin
560				assert(flushcount == beats_outstanding + 1
561					+ ((misaligned_request
562					|| misaligned_aw_request) ? 1:0));
563			// else if (faxil_rd_outstanding > 0 || M_AXI_ARVALID)
564			end else if (r_flushing)
565			begin
566				assert(beats_outstanding == flushcount);
567			end else
568				assert(beats_outstanding >= flushcount);
569		end
570	`endif
571		// }}}
572	
573		// Bus addressing
574		// {{{
575		initial	M_AXI_AWADDR = 0;
576		always @(posedge i_clk)
577		if (i_stb)
578		begin
579			M_AXI_AWADDR <= i_addr[AW-1:0];
580			if (SWAP_WSTRB)
581				M_AXI_AWADDR[AXILSB-1:0] <= 0;
582		end else if (!OPT_ALIGNMENT_ERR
583			&& ((M_AXI_AWVALID && M_AXI_AWREADY) // && misaligned_aw_request
584			|| (M_AXI_ARVALID && M_AXI_ARREADY))) // && misaligned_request))
585		begin
586			M_AXI_AWADDR[AW-1:AXILSB] <= M_AXI_AWADDR[AW-1:AXILSB] + 1;
587			M_AXI_AWADDR[AXILSB-1:0] <= 0;
588		end
589	
590		always @(*)
591			M_AXI_ARADDR = M_AXI_AWADDR;
592		// }}}
593	
594		// Is this request misaligned?
595		// {{{
596		always @(*)
597		casez(i_op[2:1])
598		// Full word
599		2'b0?: w_misaligned = (i_addr[AXILSB-1:0]+3) >= (1<<AXILSB);
600		// Half word
601		2'b10: w_misaligned = (i_addr[AXILSB-1:0]+1) >= (1<<AXILSB);
602		// Bytes are always aligned
603		2'b11: w_misaligned = 1'b0;
604		endcase
605	
606		assign	w_misalignment_err = w_misaligned && OPT_ALIGNMENT_ERR;
607		// }}}
608	
609		// wide_wdata, wide_wstrb
610		// {{{
611		always @(*)
612		if (SWAP_WSTRB)
613		begin : BACKWARDS_ORDER
614			// {{{
615			casez(i_op[2:1])
616			2'b10: wide_wdata
617				= { i_data[15:0], {(2*C_AXI_DATA_WIDTH-16){1'b0}} }
618					>> (i_addr[AXILSB-1:0] * 8);
619			2'b11: wide_wdata
620				= { i_data[7:0], {(2*C_AXI_DATA_WIDTH-8){1'b0}} }
621					>> (i_addr[AXILSB-1:0] * 8);
622			default: wide_wdata
623				= ({ i_data, {(2*C_AXI_DATA_WIDTH-32){ 1'b0 }} }
624					>> (i_addr[AXILSB-1:0] * 8));
625			endcase
626	
627			casez(i_op[2:1])
628			2'b0?: wide_wstrb
629				= { 4'b1111, {(2*C_AXI_DATA_WIDTH/8-4){1'b0}} } >> i_addr[AXILSB-1:0];
630			2'b10: wide_wstrb
631				= { 2'b11, {(2*C_AXI_DATA_WIDTH/8-2){1'b0}} } >> i_addr[AXILSB-1:0];
632			2'b11: wide_wstrb
633				= { 1'b1, {(2*C_AXI_DATA_WIDTH/8-1){1'b0}} } >> i_addr[AXILSB-1:0];
634			endcase
635			// }}}
636		end else begin : LITTLE_ENDIAN_DATA
637			// {{{
638			casez(i_op[2:1])
639			2'b10: wide_wdata
640				= { {(2*C_AXI_DATA_WIDTH-16){1'b0}}, i_data[15:0] } << (8*i_addr[AXILSB-1:0]);
641			2'b11: wide_wdata
642				= { {(2*C_AXI_DATA_WIDTH-8){1'b0}}, i_data[7:0] } << (8*i_addr[AXILSB-1:0]);
643			default: wide_wdata
644				= { {(2*C_AXI_DATA_WIDTH-32){1'b0}}, i_data }
645						<< (8*i_addr[AXILSB-1:0]);
646			endcase
647	
648			casez(i_op[2:1])
649			2'b0?: wide_wstrb
650				= { {(2*C_AXI_DATA_WIDTH/8-4){1'b0}}, 4'b1111} << i_addr[AXILSB-1:0];
651			2'b10: wide_wstrb
652				= { {(2*C_AXI_DATA_WIDTH/8-4){1'b0}}, 4'b0011} << i_addr[AXILSB-1:0];
653			2'b11: wide_wstrb
654				= { {(2*C_AXI_DATA_WIDTH/8-4){1'b0}}, 4'b0001} << i_addr[AXILSB-1:0];
655			endcase
656			// }}}
657		end
658		// }}}
659	
660		// WDATA and WSTRB
661		// {{{
662		initial	M_AXI_WDATA = 0;
663		initial	M_AXI_WSTRB = 0;
664		initial	next_wdata  = 0;
665		initial	next_wstrb  = 0;
666		always @(posedge i_clk)
667		if (i_stb)
668		begin
669			if (SWAP_WSTRB)
670			begin : BACKWARDS_ORDER_REG
671				// {{{
672				{ M_AXI_WDATA, next_wdata } <= wide_wdata;
673				{ M_AXI_WSTRB, next_wstrb } <= wide_wstrb;
674				// }}}
675			end else begin
676				// {{{
677				{ next_wdata, M_AXI_WDATA } <= wide_wdata;
678				{ next_wstrb, M_AXI_WSTRB } <= wide_wstrb;
679				// }}}
680			end
681	
682			if (OPT_ALIGNMENT_ERR)
683				{ next_wstrb, next_wdata } <= 0;
684	
685		end else if ((OPT_LOWPOWER || !OPT_ALIGNMENT_ERR) && M_AXI_WREADY)
686		begin
687			M_AXI_WDATA <= next_wdata;
688			M_AXI_WSTRB <= next_wstrb;
689			if (OPT_LOWPOWER)
690				{ next_wdata, next_wstrb } <= 0;
691		end
692		// }}}
693	
694		generate if (OPT_ALIGNMENT_ERR)
695		begin : GEN_ALIGNMENT_ERR
696			// {{{
697			// Generate an error on any misaligned request
698			assign	misaligned_request = 1'b0;
699	
700			assign	misaligned_aw_request = 1'b0;
701			assign	pending_err = 1'b0;
702			// }}}
703		end else begin : GEN_REALIGNMENT
704			// {{{
705			reg	r_misaligned_request, r_misaligned_aw_request,
706				r_pending_err;
707	
708			// misaligned_request
709			// {{{
710			initial	r_misaligned_request = 0;
711			always @(posedge i_clk)
712			if (!S_AXI_ARESETN)
713				r_misaligned_request <= 0;
714			else if (i_stb && !o_err && !i_cpu_reset && !bus_abort)
715				r_misaligned_request <= w_misaligned;
716			else if ((M_AXI_WVALID && M_AXI_WREADY)
717						|| (M_AXI_ARVALID && M_AXI_ARREADY))
718				r_misaligned_request <= 1'b0;
719	
720			assign	misaligned_request = r_misaligned_request;
721			// }}}
722	
723			// misaligned_aw_request
724			// {{{
725			initial	r_misaligned_aw_request = 0;
726			always @(posedge i_clk)
727			if (!S_AXI_ARESETN)
728				r_misaligned_aw_request <= 0;
729			else if (i_stb && !o_err && !i_cpu_reset && !write_abort)
730				r_misaligned_aw_request <= w_misaligned && i_op[0];
731			else if (M_AXI_AWREADY)
732				r_misaligned_aw_request <= 1'b0;
733	
734			assign	misaligned_aw_request = r_misaligned_aw_request;
735			// }}}
736	
737			// pending_err
738			// {{{
739			initial	r_pending_err = 1'b0;
740			always @(posedge i_clk)
741			if (i_cpu_reset || i_stb || o_err || r_flushing)
742				r_pending_err <= 1'b0;
743			else if ((M_AXI_BVALID && M_AXI_BRESP[1])
744					|| (M_AXI_RVALID && M_AXI_RRESP[1]))
745				r_pending_err <= 1'b1;
746	
747			assign	pending_err = r_pending_err;
748			// }}}
749	
750	`ifdef	FORMAL
751			always @(*)
752			if (pending_err)
753				assert(r_flushing || o_err);
754	`endif
755			// }}}
756		end endgenerate
757		// }}}
758		////////////////////////////////////////////////////////////////////////
759		//
760		// Read transaction FIFO
761		// {{{
762		////////////////////////////////////////////////////////////////////////
763		//
764		//
765	
766		// wraddr
767		// {{{
768		initial	wraddr = 0;
769		always @(posedge S_AXI_ACLK)
770		if (bus_abort || flush_request)	// bus_abort includes i_cpu_reset
771			wraddr <= 0;
772		else if ((M_AXI_ARVALID && M_AXI_ARREADY) || (M_AXI_WVALID && M_AXI_WREADY))
773			wraddr <= wraddr + 1;
774		// }}}
775	
776		// rdaddr
777		// {{{
778		initial	rdaddr = 0;
779		always @(posedge S_AXI_ACLK)
780		if (bus_abort || r_flushing)
781			rdaddr <= 0;
782		else if (M_AXI_RVALID||M_AXI_BVALID)
783			rdaddr <= rdaddr + 1;
784		// }}}
785	
786		// ar_oreg, ar_op, adr_lsb
787		// {{{
788		always @(posedge S_AXI_ACLK)
789		if (i_stb)
790			{ ar_oreg, ar_op, adr_lsb } <= { i_oreg, i_op[2:1], i_addr[AXILSB-1:0] };
791		else if ((M_AXI_ARVALID && M_AXI_ARREADY)||(M_AXI_WVALID && M_AXI_WREADY))
792			adr_lsb <= 0;
793		// }}}
794	
795		// fifo_data
796		// {{{
797		always @(posedge S_AXI_ACLK)
798		if ((M_AXI_ARVALID && M_AXI_ARREADY) || (M_AXI_WVALID && M_AXI_WREADY))
799			fifo_data[wraddr[LGPIPE-1:0]] <= { M_AXI_ARVALID, ar_oreg,ar_op,
800					misaligned_request, adr_lsb };
801	
802		always @(*)
803			fifo_read_data = fifo_data[rdaddr[LGPIPE-1:0]];
804	
805		assign	{ fifo_read_op, fifo_return_reg, fifo_op,
806				fifo_misaligned, fifo_lsb } = fifo_read_data;
807		// }}}
808		// }}}
809		////////////////////////////////////////////////////////////////////////
810		//
811		// Read return generation
812		// {{{
813		////////////////////////////////////////////////////////////////////////
814		//
815		//
816	
817		// o_valid
818		// {{{
819		initial	o_valid = 1'b0;
820		always @(posedge i_clk)
821		if (i_cpu_reset || r_flushing)
822			o_valid <= 1'b0;
823		else if (OPT_ALIGNMENT_ERR && i_stb && w_misaligned)
824			o_valid <= 1'b0;
825		else
826			o_valid <= M_AXI_RVALID && !M_AXI_RRESP[1] // && !pending_err
827					&& !fifo_misaligned;
828		// }}}
829	
830		// o_wreg
831		// {{{
832		always @(posedge i_clk)
833			o_wreg <= fifo_return_reg;
834		// }}}
835	
836		// o_result, misdata
837		// {{{
838		// Need to realign any returning data
839		// wide_return
840		// {{{
841		always @(*)
842		begin
843			if (SWAP_WSTRB)
844			begin
845				if (fifo_misaligned && !OPT_ALIGNMENT_ERR)
846					wide_return = { misdata, M_AXI_RDATA }
847								<< (8*fifo_lsb);
848				else
849					wide_return = { M_AXI_RDATA, {(DW){1'b0}} }
850								<< (8*fifo_lsb);
851	
852			end else begin
853				if (fifo_misaligned && !OPT_ALIGNMENT_ERR)
854					wide_return = { M_AXI_RDATA, misdata } >> (8*fifo_lsb);
855				else
856					wide_return = { {(C_AXI_DATA_WIDTH){1'b0}}, M_AXI_RDATA }
857						>> (8*fifo_lsb);
858			end
859	
860			if (OPT_LOWPOWER && (!M_AXI_RVALID || M_AXI_RRESP[1]))
861				wide_return = 0;
862		end
863	
864		always @(*)
865		begin
866			if (SWAP_WSTRB)
867			begin
868				pre_result = 0;
869	
870				casez(fifo_op)
871				2'b10: pre_result[15:0] = {
872						wide_return[(2*DW)-1:(2*DW)-16] };
873				2'b11: pre_result[7:0] = {
874						wide_return[(2*DW)-1:(2*DW)-8] };
875				default: pre_result[31:0] = wide_return[(2*DW-1):(2*DW-32)];
876				endcase
877	
878			end else
879				pre_result = wide_return[31:0];
880		end
881		// }}}
882	
883		// misdata
884		// {{{
885		always @(posedge i_clk)
886		if (OPT_ALIGNMENT_ERR)
887			misdata <= 0;
888		else if (M_AXI_RVALID)
889		begin
890			if (fifo_misaligned)
891				misdata <= M_AXI_RDATA;
892			else
893				misdata <= 0;
894		end
895		// }}}
896	
897		// o_result
898		// {{{
899		always @(posedge i_clk)
900		if (OPT_LOWPOWER && (!S_AXI_ARESETN || r_flushing || i_cpu_reset))
901		begin
902			o_result <= 0;
903		end else if (!OPT_LOWPOWER || M_AXI_RVALID)
904		begin
905	
906			o_result <= pre_result[31:0];
907	
908			if (OPT_SIGN_EXTEND)
909			begin
910				// {{{
911				// Optionally sign extend the return result.
912				case(fifo_op)
913				2'b10: o_result[31:16] <= {(16){pre_result[15]}};
914				2'b11: o_result[31: 8] <= {(24){pre_result[7]}};
915				default: begin end
916				endcase
917				// }}}
918			end else if (fifo_op[1])
919			begin
920				// {{{
921				if (fifo_op[0])
922					o_result[31: 8] <= 0;
923				else
924					o_result[31:16] <= 0;
925				// }}}
926			end
927	
928		end
929		// }}}
930		// }}}
931	
932		// o_err - report bus errors back to the CPU
933		// {{{
934		initial	o_err = 1'b0;
935		always @(posedge i_clk)
936		if (i_cpu_reset || r_flushing || o_err)
937			o_err <= 1'b0;
938		else if (OPT_ALIGNMENT_ERR && i_stb && w_misaligned)
939			o_err <= 1'b1;
940		else if (M_AXI_BVALID || M_AXI_RVALID)
941			o_err <= (M_AXI_BVALID && M_AXI_BRESP[1])
942				|| (M_AXI_RVALID && M_AXI_RRESP[1]);
943		else
944			o_err <= 1'b0;
945		// }}}
946	
947		// Return xREADY -- always ready
948		// {{{
949		assign	M_AXI_RREADY = 1;
950		assign	M_AXI_BREADY = 1;
951		// }}}
952	
953		// AxPROT -- CPU data
954		// {{{
955		assign	M_AXI_AWPROT = 3'b000;
956		assign	M_AXI_ARPROT = 3'b000;
957	
958		// }}}
959		// }}}
960	
961		// Make verilator happy
962		// {{{
963		// verilator coverage_off
964		// verilator lint_off UNUSED
965		wire	unused;
966		assign	unused = &{ 1'b0, M_AXI_RRESP[0], M_AXI_BRESP[0], i_lock,
967				// i_addr[31:C_AXI_ADDR_WIDTH],
968				(&i_addr),
969				pending_err, adr_lsb, fifo_read_op,
970				none_outstanding };
971	
972		generate if (SWAP_WSTRB)
973		begin : GEN_UNUSED
974			wire	wide_unused;
975	
976			if (SWAP_WSTRB)
977			begin : UNUSED_SWAP
978				assign	wide_unused = &{ 1'b0,
979						wide_return[2*DW-32-1:0] };
980			end else begin : UNUSED
981				assign	wide_unused = &{ 1'b0, wide_return[2*DW-1:32] };
982			end
983		end endgenerate
984		// verilator lint_on  UNUSED
985		// verilator coverage_on
986		// }}}
