1099		always @(*)
1100			f_fifo_fill = wraddr - rdaddr;
1101	
1102		always @(*)
1103		begin
1104			if (misaligned_request)
1105				`ASSERT(M_AXI_WVALID || M_AXI_ARVALID);
1106			if (misaligned_aw_request)
1107				`ASSERT(M_AXI_AWVALID);
1108	
1109			if (M_AXI_ARVALID || faxil_rd_outstanding > 0)
1110			begin
1111				assert(faxil_wr_outstanding == 0
1112					&& faxil_awr_outstanding == 0);
1113				assert(!M_AXI_AWVALID);
1114				assert(!M_AXI_WVALID);
1115			end
1116	
1117			if (faxil_wr_outstanding > 0 || faxil_awr_outstanding > 0
1118				|| M_AXI_AWVALID || M_AXI_WVALID)
1119			begin
1120				assert(faxil_rd_outstanding == 0);
1121				assert(!M_AXI_ARVALID);
1122			end
1123	
1124			// Rule: Only one of the two VALID's may be valid, never both
1125			`ASSERT(!M_AXI_RVALID || (!M_AXI_AWVALID && !M_AXI_WVALID));
1126	
1127			assert(beats_outstanding
1128				+ ((misaligned_request && !misaligned_aw_request && M_AXI_WVALID) ? 1:0)
1129				+ ((M_AXI_WVALID && !M_AXI_AWVALID) ? 1:0)
1130				== faxil_rd_outstanding + faxil_awr_outstanding);
1131	
1132			assert(beats_outstanding
1133				+ ((misaligned_aw_request && !misaligned_request) ? 1:0)
1134				+ ((M_AXI_AWVALID && !M_AXI_WVALID) ? 1:0)
1135				== faxil_rd_outstanding + faxil_wr_outstanding);
1136	
1137			if (OPT_ALIGNMENT_ERR && !r_flushing
1138					&& (faxil_rd_outstanding > 0 || M_AXI_ARVALID))
1139			begin
1140				assert(f_fifo_fill == faxil_rd_outstanding);
1141			end else if (OPT_ALIGNMENT_ERR && !r_flushing
1142					&& (faxil_wr_outstanding > 0 || M_AXI_WVALID))
1143				assert(f_fifo_fill == faxil_wr_outstanding);
