1197				&& (!M_AXI_BVALID || !M_AXI_BRESP[1])
1198				&& (!OPT_ALIGNMENT_ERR || !w_misaligned))
1199					== (M_AXI_AWVALID && M_AXI_WVALID));
1200		end
