1270		//
1271		// FIFO property checking
1272		// {{{
1273		////////////////////////////////////////////////////////////////////////
1274		//
1275		//
1276	
1277		always @(*)
1278		begin
1279			// {{{
1280			f_next_addr = f_first_addr + 1;
1281			f_last_written = wraddr - 1;
1282	
1283			f_penu_addr = rdaddr + 1;
1284			f_penu_data = fifo_data[f_penu_addr[LGPIPE-1:0]];
1285	
1286			f_clrfifo = (!S_AXI_ARESETN || bus_abort || flush_request);
