1291	
1292			f_distance_to_first = f_first_addr - rdaddr;
1293			f_distance_to_next  = f_next_addr  - rdaddr;
1294	
1295			f_first_in_fifo = (f_distance_to_first < f_fifo_fill) && (f_fifo_fill > 0);
1296			f_next_in_fifo  = (f_distance_to_next < f_fifo_fill) && (f_fifo_fill > 0);
1297	
1298			f_return_reg = fifo_return_reg;
1299	
1300			f_first_return_reg = f_first_data[AXILLSB+3 +: 5];
1301			f_next_return_reg  = f_next_data[AXILLSB+3 +: 5];
1302			f_penu_return_reg  = f_penu_data[AXILLSB+3 +: 5];
1303	
1304			f_first_misaligned = f_first_data[AXILLSB];
1305			f_next_misaligned = f_next_data[AXILLSB];
1306			f_this_misaligned = fifo_read_data[AXILLSB];
1307			f_penu_misaligned = f_penu_data[AXILLSB];
1308	
1309			f_first_read_cycle = f_first_data[FIFO_WIDTH-1];
1310			f_next_read_cycle = f_next_data[FIFO_WIDTH-1];
1311			f_this_read_cycle = fifo_read_data[FIFO_WIDTH-1];
1312			f_penu_read_cycle = f_penu_data[FIFO_WIDTH-1];
