1314		end
1315	
1316		always @(*)
1317		if (r_flushing && !f_clrfifo)
1318			assert(rdaddr == wraddr);
1319	
1320		always @(*)
1321		if (!f_clrfifo)
1322		begin
1323			if (f_first_in_fifo)
1324				`ASSERT(f_first_data == fifo_data[f_first_addr]);
