1345			f_fsmfifo <= 2'b01;
1346		2'b01: if (f_rdfifo && rdaddr == f_first_addr)
1347			f_fsmfifo <= 2'b00;
1348			else if (f_wrfifo && wraddr == f_next_addr)
1349			f_fsmfifo <= 2'b10;
