1355	
1356		always @(*)
1357		if (!f_clrfifo)
1358		case(f_fsmfifo)
1359		2'b00: begin
1360			// {{{
1361			`ASSERT(!f_first_in_fifo);
1362			end
1363			// }}}
1364		2'b01: begin
1365			// {{{
1366			`ASSERT(f_fifo_fill >= 1);
1367			`ASSERT(f_first_in_fifo);
1368			end
1369			// }}}
1370		2'b10: begin
1371			// {{{
1372			`ASSERT(f_fifo_fill >= 2);
1373			`ASSERT(f_first_in_fifo);
1374			`ASSERT(f_next_in_fifo);
1375			end
1376			// }}}
1377		2'b11: begin
1378			// {{{
1379			`ASSERT(f_fifo_fill >= 1);
1380			`ASSERT(f_next_in_fifo);
1381			end
1382			// }}}
1383		endcase
