1386		// { ar_oreg, ar_op, misaligned_request, M_AXI_ARADDR[AXILLSB-1:0] };
1387	
1388		// cpu_gie checks
1389		// {{{
1390		always @(*)
1391		if (M_AXI_ARVALID)
1392			`ASSERT(cpu_gie == ar_oreg[4]);
1393	
1394		always @(*)
1395		if (!f_clrfifo && f_fifo_fill != 0)
1396		begin
1397			if (M_AXI_ARVALID || M_AXI_WVALID || M_AXI_AWVALID)
1398				`ASSERT(cpu_gie == ar_oreg[4]);
1399	
1400			if ((!f_first_in_fifo || rdaddr != f_first_addr)
1401					&& (!f_next_in_fifo || rdaddr != f_next_addr)
1402					&& (f_fifo_fill > 0))
