1672			.i_stb(i_stb),
1673			.i_pipe_stalled(o_pipe_stalled),
1674			.i_clear_cache(1'b0),
1675			.i_lock(i_lock), .i_op(i_op), .i_addr(i_addr),
1676			.i_data(i_data), .i_oreg(i_oreg), .i_busy(o_busy),
1677				.i_areg(f_areg),
1678			.i_rdbusy(o_rdbusy), .i_valid(o_valid), .i_done(f_done),
1679			.i_err(o_err), .i_wreg(o_wreg), .i_result(o_result),
1680			.f_outstanding(cpu_outstanding),
1681			.f_pc(cpu_pc), .f_gie(cpu_gie), .f_read_cycle(cpu_read_cycle),
1682			.f_last_reg(cpu_last_reg), .f_addr_reg(cpu_addr_reg)
1683			// }}}
1684		);
1685	
1686		always @(*)
1687		if (flush_request)
1688		begin
1689			`ASSERT(cpu_outstanding == 0 || o_err);
1690		end else if (r_flushing)
1691		begin
1692			`ASSERT(o_err || cpu_outstanding == 0);
1693		end else if (OPT_ALIGNMENT_ERR)
1694		begin
1695			if (!o_err)
1696			`ASSERT(cpu_outstanding == (beats_outstanding - flushcount)
1697				+ ((M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID) ? 1:0)
1698				+ ((o_valid || f_done) ? 1:0));
1699			// else `ASSERT(cpu_outstanding == flushcount);
1700		end
1701	
1702		always @(*)
1703		if (o_err && beats_outstanding > 0)
1704			`ASSERT(r_flushing);
1705	
1706		always @(*)
1707		if (!o_err && cpu_outstanding > 0)
1708		begin
1709			if (faxil_rd_outstanding > 0 || M_AXI_ARVALID || o_rdbusy)
1710			begin
1711				assert(cpu_read_cycle);
1712			end else if (faxil_awr_outstanding > 0 || faxil_wr_outstanding > 0
1713					|| M_AXI_AWVALID || M_AXI_WVALID)
1714				assert(!cpu_read_cycle);
1715		end
1716		// }}}
1717		////////////////////////////////////////////////////////////////////////
1718		//
1719		// Cover properties
1720		// {{{
1721		////////////////////////////////////////////////////////////////////////
1722		//
1723		//
1724		reg	[LGPIPE:0]	cvr_writes, cvr_reads, cvr_valids;
1725		reg			cvr_idle;
1726	
1727		always @(*)
1728		begin
1729			cvr_idle = 1;
1730			if (i_cpu_reset || o_err || f_done)
1731				cvr_idle = 1'b0;
1732			if (M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID)
1733				cvr_idle = 1'b0;
1734			if (faxil_awr_outstanding > 0)
1735				cvr_idle = 1'b0;
1736			if (faxil_wr_outstanding > 0)
1737				cvr_idle = 1'b0;
1738			if (faxil_rd_outstanding > 0)
1739				cvr_idle = 1'b0;
1740		end
1741	
1742		initial	cvr_writes = 0;
1743		always @(posedge i_clk)
1744		if (i_cpu_reset || o_err)
1745			cvr_writes <= 0;
1746		else if (M_AXI_BVALID&& !misaligned_response_pending  && !(&cvr_writes))
1747			cvr_writes <= cvr_writes + 1;
1748	
1749		initial	cvr_reads = 0;
1750		always @(posedge i_clk)
1751		if (i_cpu_reset || o_err)
1752			cvr_reads <= 0;
1753		else if (M_AXI_RVALID && !misaligned_response_pending && !(&cvr_reads))
1754			cvr_reads <= cvr_reads + 1;
1755	
1756		initial	cvr_valids = 0;
1757		always @(posedge i_clk)
1758		if (i_cpu_reset || o_err)
1759			cvr_valids <= 0;
1760		else if (o_valid)
1761			cvr_valids <= cvr_valids + 1;
1762	
1763		// Cover a write response
1764		always @(posedge i_clk)
1765			cover(M_AXI_BVALID && !M_AXI_BRESP[1]);
1766		always @(posedge i_clk)
1767			cover(M_AXI_BVALID &&  M_AXI_BRESP[1]);
1768	
1769		always @(posedge i_clk)
1770			cover(M_AXI_RVALID && !M_AXI_RRESP[1]);
1771		always @(posedge i_clk)
1772			cover(M_AXI_RVALID &&  M_AXI_RRESP[1]);
1773	
1774	
1775		always @(posedge i_clk)
1776		if (cvr_idle)
1777		begin
1778			cover(cvr_writes >  3);
1779			cover(cvr_reads  >  3);
1780			cover(cvr_valids >  3);
1781	
1782			cover(cvr_writes > (1<<LGPIPE));
1783			cover(cvr_reads  > (1<<LGPIPE));
1784			cover(cvr_valids > (1<<LGPIPE));
1785	
1786			cover(cvr_writes > (1<<LGPIPE)+2);
1787			cover(cvr_reads  > (1<<LGPIPE)+2);
1788			cover(cvr_valids > (1<<LGPIPE)+2);
1789		end
1790	
1791		generate if (!OPT_ALIGNMENT_ERR)
1792		begin
1793			reg	[LGPIPE:0]	cvr_unaligned_writes,
1794						cvr_unaligned_reads;
1795	
1796			initial	cvr_writes = 0;
1797			always @(posedge i_clk)
1798			if (i_cpu_reset || o_err)
1799				cvr_unaligned_writes <= 0;
1800			else if (i_stb && i_op[0] && w_misaligned)
1801				cvr_unaligned_writes <= cvr_unaligned_writes + 1;
1802	
1803			initial	cvr_reads = 0;
1804			always @(posedge i_clk)
1805			if (i_cpu_reset || o_err)
1806				cvr_unaligned_reads <= 0;
1807			else if (i_stb && !i_op[0] && w_misaligned)
1808				cvr_unaligned_reads <= cvr_unaligned_reads + 1;
1809	
1810			always @(posedge i_clk)
1811			if (cvr_idle)
1812			begin
1813				cover(cvr_unaligned_writes >  3);
1814				cover(cvr_unaligned_reads  >  3);
1815	
1816				cover(cvr_unaligned_writes > (1<<LGPIPE));
1817				cover(cvr_unaligned_reads  > (1<<LGPIPE));
1818			end
1819		end endgenerate
1820	
1821		// }}}
1822		////////////////////////////////////////////////////////////////////////
1823		//
1824		// Careless assumptions
1825		// {{{
1826		////////////////////////////////////////////////////////////////////////
1827		//
1828		//
1829	
1830		always @(*)
1831		if (!OPT_ALIGNMENT_ERR)
1832		begin
1833			if (!r_flushing && !o_err)
1834			`BMC_ASSERT(cpu_outstanding <= beats_outstanding
1835				+ ((M_AXI_AWVALID || M_AXI_WVALID || M_AXI_ARVALID) ? 1:0)
1836				+ ((o_valid || f_done) ? 1:0));
1837	
1838			if (!r_flushing && cpu_read_cycle)
1839			`BMC_ASSERT(cpu_outstanding >= (f_done ? 1:0)
1840						+ faxil_rd_outstanding[F_LGDEPTH-1:1]);
1841			else if (!r_flushing)
1842			`BMC_ASSERT(cpu_outstanding >= (f_done ? 1:0)
1843						+ faxil_wr_outstanding[F_LGDEPTH-1:1]);
1844	
1845			if (!r_flushing && !o_err)
1846			assert(f_fifo_fill == beats_outstanding
1847				+ ((misaligned_aw_request && !misaligned_request) ? 1:0)
1848					+ (M_AXI_AWVALID && !M_AXI_WVALID));
1849	
1850			if (!r_flushing && !o_err)
1851				`BMC_ASSERT((cpu_outstanding == 0) == (!M_AXI_AWVALID
1852					&& !M_AXI_WVALID && !M_AXI_ARVALID
1853					&& (beats_outstanding + (f_done ? 1:0) == 0)));
1854			else if (o_err)
1855				`BMC_ASSERT(cpu_outstanding > 0);
1856	
1857	
1858			if (!r_flushing && !o_err && cpu_outstanding == (f_done ? 1:0))
1859				`BMC_ASSERT(beats_outstanding == 0
1860					&& !M_AXI_AWVALID && !M_AXI_WVALID
1861					&& !M_AXI_ARVALID);
1862		end
1863	
1864		// }}}
1865	`endif
1866	// }}}
1867	endmodule
1868

